//! Actions-only real Router/TLS/Common account task -> original Group.Update
//! durable partial DATA -> original reply. No SDK/device or relationship WRITE.
use super::*;
fn installed(root:&str,port:u16,timeout:u64)->AccountConfig{let mut c=config(root,port,timeout);c.profile.relation_events=Some(n::group_events::NativeRelationEventsConfig{group_updates:true});c}
fn args(base:i64,update:i64,label:&[u8])->Vec<u8>{
    let mut b=Writer::new();b.u32(2).unwrap();for(label,flags)in[(label,1),(b"private-removal".as_slice(),20)]{b.bytes(label).unwrap();b.u32(flags).unwrap();b.bytes(b"private-remark").unwrap();b.bytes(b"").unwrap();b.properties(&[]).unwrap();}let b=b.finish();let base=base.to_string();let update=update.to_string();let mut w=Writer::versioned().unwrap();w.bytes(b"Group.Update").unwrap();w.properties(&[RpcProperty{key:b"Group.GroupId",value:b"1-2"},RpcProperty{key:b"Group.LastUpdateTime",value:base.as_bytes()},RpcProperty{key:b"Group.UpdateTime",value:update.as_bytes()}]).unwrap();w.bytes(b.expose_to_transport()).unwrap();w.finish().expose_to_transport().to_vec()
}
fn update(id:i32,base:i64,time:i64,label:&[u8])->Vec<u8>{direct(id,n::rpc_incoming::ONLINE_MESSAGE_METHOD.as_bytes(),&args(base,time,label),b"MessageReceiver",None)}
fn stored(db:&crate::platform::db::Database)->i64{db.with_conn(|c|c.query_row("SELECT COUNT(*) FROM app_voice_relation_events",[],|r|r.get(0)).map_err(|_|"fixture")).unwrap()}
async fn login_host(peer:&mut CommonPeer){let p=peer.next().await.unwrap();let login=decode_request(&p[1..]).unwrap();peer.send(&[reply(login.call_id,&login_result())]).await;let(_,flag)=hosting_call(peer).await;assert_eq!(flag,b"4");}
#[tokio::test]async fn group_event_account_commits_partial_chain_gap_stale_and_conflict_before_original_replies_without_write(){Box::pin(async{
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=listener.local_addr().unwrap().port();let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let manager=AccountManager::new(temp.database.clone());let cfg=installed(&cert.root,port,3000);assert!(cfg.profile.relation_updates.is_none()&&cfg.profile.im_sync.is_none());let account=manager.create(cfg,100).await.unwrap().account;let line=account.line_id.clone();let observed=temp.database.clone();let(done,finished)=tokio::sync::oneshot::channel();
    let serving=tokio::spawn(Box::pin(async move{bounded(async move{let mut peer=CommonPeer::open(listener,server).await;login_host(&mut peer).await;
        for(id,base,time,expected)in [(91,0,1,1),(92,1,2,2),(93,4,5,3),(94,-1,0,4),(95,1,2,4)]{peer.send(&[update(id,base,time,b"a")]).await;next_reply(&mut peer,id,true).await;assert_eq!(stored(&observed),expected,"SQL committed before physical positive reply");}
        peer.send(&[update(96,1,2,b"changed")]).await;next_reply(&mut peer,96,false).await;assert_eq!(stored(&observed),4);assert_eq!(count(&observed),0);done.send(()).unwrap();finish_account(&mut peer).await;
    }).await}));
    bounded(manager.start(&line,account.revision,100)).await.unwrap();bounded(finished).await.unwrap();let rows=manager.relation_event_history(&line,128).unwrap();assert_eq!(rows.iter().map(|r|r.continuity.as_str()).collect::<Vec<_>>(),["stale","gap","partial_chain","unseeded"]);assert!(rows.iter().all(|r|!r.full_roster_verified));assert!(manager.relation_write_history(&line,128).unwrap().is_empty());assert!(manager.relation_intent_history(&line,128).unwrap().is_empty());let view=manager.get(&line,100).await.unwrap();assert_eq!(view.phase,"hosted");assert_eq!(view.relation_events_supported,Some(true));assert_eq!(view.relation_updates_supported,Some(false));assert_eq!(view.last_error,Some("app_account_relation_event_conflict"));assert!(!view.incoming_call_ready&&!view.outbound_authorized);assert!(manager.im_messages(&line,128).unwrap().is_empty());assert!(manager.messages(&line,128).unwrap().is_empty());assert_eq!(temp.database.get_recent_app_events(Some(&line),128).unwrap().iter().filter(|e|e.event_type=="app_voice.relation_event_observed").count(),4);
    assert!(!bounded(manager.stop(&line,account.revision,100)).await.unwrap().io_cleanup_required);bounded(serving).await.unwrap();assert!(!temp.database.with_conn(|c|n::account_runs::ownership_pending(c,&line)).unwrap());bounded(manager.delete(&line,account.revision)).await.unwrap();assert_eq!(stored(&temp.database),0);let heads:i64=temp.database.with_conn(|c|c.query_row("SELECT COUNT(*) FROM app_voice_relation_event_heads",[],|r|r.get(0)).map_err(|_|"fixture")).unwrap();assert_eq!(heads,0);
}).await;}
async fn early(expired:bool){
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=listener.local_addr().unwrap().port();let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let manager=AccountManager::new(temp.database.clone());let account=manager.create(installed(&cert.root,port,if expired{100}else{3000}),100).await.unwrap().account;let line=account.line_id.clone();let db=temp.database.clone();let(done,finished)=tokio::sync::oneshot::channel();
    let serving=tokio::spawn(Box::pin(async move{bounded(async move{let mut peer=CommonPeer::open(listener,server).await;let p=peer.next().await.unwrap();let login=decode_request(&p[1..]).unwrap();peer.send(&[reply(login.call_id,&login_result()),update(91,0,1,b"a")]).await;
        loop{let p=peer.next().await.unwrap();assert_eq!(p[0],0,"no unconfirmed group reply");let req=decode_request(&p[1..]).unwrap();assert_eq!(req.method,n::rpc_batch::SWAP_CALLS_METHOD.as_bytes());let mut r=Reader::versioned(req.arguments).unwrap();r.bytes().unwrap();r.bytes().unwrap();let payload=n::rpc_batch::read_payload(&mut r).unwrap();let seq=payload.requests.keys().copied().next();if seq.is_some(){if expired{tokio::time::sleep(Duration::from_millis(150)).await;}assert_eq!(stored(&db),0);}peer.send(&[reply(req.call_id,&n::runtime_backend::tests::swap_result(seq,true,payload.fields))]).await;if seq.is_some(){break;}}
        next_reply(&mut peer,91,!expired).await;assert_eq!(stored(&db),i64::from(!expired));done.send(()).unwrap();finish_account(&mut peer).await;
    }).await}));
    bounded(manager.start(&line,account.revision,100)).await.unwrap();bounded(finished).await.unwrap();assert_eq!(manager.relation_event_history(&line,128).unwrap().len(),usize::from(!expired));assert!(!bounded(manager.stop(&line,account.revision,100)).await.unwrap().io_cleanup_required);bounded(serving).await.unwrap();assert!(!temp.database.with_conn(|c|n::account_runs::ownership_pending(c,&line)).unwrap());
}
#[tokio::test]async fn group_event_account_early_update_waits_for_original_hosting_ack_and_shared_queue(){Box::pin(early(false)).await;}
#[tokio::test]async fn group_event_account_expired_early_event_nacks_without_sql_or_extended_deadline(){Box::pin(early(true)).await;}
#[tokio::test]async fn group_event_account_sql_event_failure_rolls_back_observation_head_and_preserves_original_stop_join(){Box::pin(async{
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=listener.local_addr().unwrap().port();let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let manager=AccountManager::new(temp.database.clone());let account=manager.create(installed(&cert.root,port,3000),100).await.unwrap().account;let line=account.line_id.clone();temp.database.with_conn(|c|c.execute_batch("CREATE TRIGGER fail_relation_event BEFORE INSERT ON app_events WHEN NEW.event_type='app_voice.relation_event_observed' BEGIN SELECT RAISE(ABORT,'fixture'); END").map_err(|_|"fixture")).unwrap();let(done,finished)=tokio::sync::oneshot::channel();
    let serving=tokio::spawn(Box::pin(async move{bounded(async move{let mut peer=CommonPeer::open(listener,server).await;login_host(&mut peer).await;peer.send(&[update(91,0,1,b"a")]).await;next_reply(&mut peer,91,false).await;done.send(()).unwrap();finish_account(&mut peer).await;}).await}));
    bounded(manager.start(&line,account.revision,100)).await.unwrap();bounded(finished).await.unwrap();assert_eq!(stored(&temp.database),0);let heads:i64=temp.database.with_conn(|c|c.query_row("SELECT COUNT(*) FROM app_voice_relation_event_heads",[],|r|r.get(0)).map_err(|_|"fixture")).unwrap();assert_eq!(heads,0);assert!(temp.database.get_recent_app_events(Some(&line),128).unwrap().is_empty());let view=manager.get(&line,100).await.unwrap();assert_eq!(view.phase,"hosted");assert_eq!(view.last_error,Some("app_account_relation_event_storage_failed"));assert!(!bounded(manager.stop(&line,account.revision,100)).await.unwrap().io_cleanup_required);bounded(serving).await.unwrap();
}).await;}
#[tokio::test]async fn group_event_account_batch_persists_before_epoch_result_and_direct_duplicate_requires_new_receipt(){Box::pin(async{
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=listener.local_addr().unwrap().port();let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let manager=AccountManager::new(temp.database.clone());let account=manager.create(installed(&cert.root,port,3000),100).await.unwrap().account;let line=account.line_id.clone();let db=temp.database.clone();let(done,finished)=tokio::sync::oneshot::channel();
    let serving=tokio::spawn(Box::pin(async move{bounded(async move{let mut peer=CommonPeer::open(listener,server).await;login_host(&mut peer).await;let p=peer.next().await.unwrap();let req=decode_request(&p[1..]).unwrap();assert_eq!(req.method,n::rpc_batch::SWAP_CALLS_METHOD.as_bytes());let mut r=Reader::versioned(req.arguments).unwrap();r.bytes().unwrap();r.bytes().unwrap();let data=n::rpc_batch::read_payload(&mut r).unwrap();let mut w=Writer::new();w.boolean(true).unwrap();for v in [9,1,1,data.fields[0],data.fields[1],data.fields[2]]{w.u32(v).unwrap();}w.u32(1).unwrap();w.i32(1).unwrap();w.bytes(n::rpc_incoming::ONLINE_MESSAGE_METHOD.as_bytes()).unwrap();w.bytes(&args(0,1,b"a")).unwrap();w.properties(&[RpcProperty{key:b"id",value:b"MessageReceiver"}]).unwrap();w.u32(0).unwrap();w.properties(&[]).unwrap();w.bytes(b"").unwrap();peer.send(&[reply(req.call_id,w.finish().expose_to_transport())]).await;
        loop{let p=peer.next().await.unwrap();assert_eq!(p[0],0);let req=decode_request(&p[1..]).unwrap();assert_eq!(req.method,n::rpc_batch::SWAP_CALLS_METHOD.as_bytes());let mut r=Reader::versioned(req.arguments).unwrap();r.bytes().unwrap();r.bytes().unwrap();let data=n::rpc_batch::read_payload(&mut r).unwrap();assert!(data.requests.is_empty());let seen=data.results.contains_key(&1);if seen{assert_eq!(data.results[&1].result_stream,[0,1,0,0,0,0]);assert_eq!(stored(&db),1);}peer.send(&[reply(req.call_id,&n::runtime_backend::tests::swap_result(None,true,data.fields))]).await;if seen{break;}}
        peer.send(&[update(91,0,1,b"a")]).await;next_reply(&mut peer,91,true).await;assert_eq!(stored(&db),1);done.send(()).unwrap();finish_account(&mut peer).await;
    }).await}));
    bounded(manager.start(&line,account.revision,100)).await.unwrap();bounded(finished).await.unwrap();assert_eq!(manager.relation_event_history(&line,128).unwrap().len(),1);assert!(manager.relation_write_history(&line,128).unwrap().is_empty());assert!(!bounded(manager.stop(&line,account.revision,100)).await.unwrap().io_cleanup_required);bounded(serving).await.unwrap();assert!(!temp.database.with_conn(|c|n::account_runs::ownership_pending(c,&line)).unwrap());
}).await;}
